{"file_text": "@page "/apply"
@rendermode InteractiveServer
@using sv_c82fb35c6d524482b5b6bd2fd93c487b.Models
@using sv_c82fb35c6d524482b5b6bd2fd93c487b.Components.Pages.JobApplication
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4">
    <h1 class="mb-4">Job Application</h1>

    @if (!_submitted)
    {
        <StepIndicator CurrentStep="_currentStep"
                       CompletedSteps="_completedSteps"
                       OnStepClicked="GoToStep" />

        <div class="card mt-4">
            <div class="card-body">
                @switch (_currentStep)
                {
                    case 1:
                        <StepPersonalInfo FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                                          FullNameChanged="v => _fullName = v"
                                          EmailChanged="v => _email = v"
                                          PhoneChanged="v => _phone = v"
                                          AddressChanged="v => _address = v"
                                          ValidationError="@_validationError"
                                          OnNext="HandlePersonalInfoNext" />
                        break;
                    case 2:
                        <StepWorkHistory Entries="_workEntries"
                                         ValidationError="@_validationError"
                                         OnBack="GoBack"
                                         OnNext="HandleWorkHistoryNext" />
                        break;
                    case 3:
                        <StepReferences References="_references"
                                        ValidationError="@_validationError"
                                        OnBack="GoBack"
                                        OnNext="HandleReferencesNext" />
                        break;
                    case 4:
                        <StepCoverLetter CoverLetter="@_coverLetter"
                                         CoverLetterChanged="v => _coverLetter = v"
                                         ValidationError="@_validationError"
                                         OnBack="GoBack"
                                         OnNext="HandleCoverLetterNext" />
                        break;
                    case 5:
                        <StepReview FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                                    WorkEntries="_workEntries" References="_references"
                                    CoverLetter="@_coverLetter"
                                    IsSubmitting="_isSubmitting"
                                    SubmitError="@_submitError"
                                    OnEdit="GoToStep"
                                    OnSubmit="HandleSubmit" />
                        break;
                }
            </div>
        </div>
    }
    else
    {
        <div class="card mt-4">
            <div class="card-body text-center py-5">
                <div class="text-success mb-3">
                    <svg xmlns="http://www.w3.org/2000/svg" width="64" height="64" fill="currentColor" viewBox="0 0 16 16">
                        <path d="M16 8A8 8 0 1 1 0 8a8 8 0 0 1 16 0m-3.97-3.03a.75.75 0 0 0-1.08.022L7.477 9.417 5.384 7.323a.75.75 0 0 0-1.06 1.06L6.97 11.03a.75.75 0 0 0 1.079-.02l3.992-4.99a.75.75 0 0 0-.01-1.05z"/>
                    </svg>
                </div>
                <h2 class="text-success">Application Submitted!</h2>
                <p class="lead mt-3">Your application has been received.</p>
                <p class="fs-5">Application ID: <strong>@_applicationId</strong></p>
                <p class="text-muted">Please save this ID for your records.</p>
            </div>
        </div>
    }
</div>

@code {
    private int _currentStep = 1;
    private HashSet<int> _completedSteps = new();
    private string? _validationError;

    // Step 1 state
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2 state
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };

    // Step 3 state
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 state
    private string _coverLetter = "";

    // Submission state
    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;
    private string? _submitError;

    private void GoToStep(int step)
    {
        if (step < _currentStep || _completedSteps.Contains(step) || step == _currentStep)
        {
            _validationError = null;
            _currentStep = step;
        }
    }

    private void GoBack()
    {
        if (_currentStep > 1)
        {
            _validationError = null;
            _currentStep--;
        }
    }

    private async Task HandlePersonalInfoNext()
    {
        _validationError = null;

        if (string.IsNullOrWhiteSpace(_fullName))
        { _validationError = "Full name is required."; return; }
        if (string.IsNullOrWhiteSpace(_email))
        { _validationError = "Email is required."; return; }
        if (string.IsNullOrWhiteSpace(_phone))
        { _validationError = "Phone number is required."; return; }
        if (string.IsNullOrWhiteSpace(_address))
        { _validationError = "Address is required."; return; }

        var emailValid = await ApplicationService.ValidateEmailAsync(_email);
        if (!emailValid)
        { _validationError = "Please enter a valid email address."; return; }

        _completedSteps.Add(1);
        _currentStep = 2;
    }

    private void HandleWorkHistoryNext()
    {
        _validationError = null;

        foreach (var entry in _workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            { _validationError = "Company name and job title are required for all entries."; return; }
            if (entry.StartDate == default)
            { _validationError = "Start date is required for all entries."; return; }
        }

        _completedSteps.Add(2);
        _currentStep = 3;
    }

    private void HandleReferencesNext()
    {
        _validationError = null;

        foreach (var r in _references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email))
            { _validationError = "Name and email are required for all references."; return; }
        }

        _completedSteps.Add(3);
        _currentStep = 4;
    }

    private void HandleCoverLetterNext()
    {
        _validationError = null;

        if (string.IsNullOrWhiteSpace(_coverLetter))
        { _validationError = "Cover letter is required."; return; }

        _completedSteps.Add(4);
        _currentStep = 5;
    }

    private async Task HandleSubmit()
    {
        _isSubmitting = true;
        _submitError = null;

        try
        {
            var application = new JobApplication(
                new PersonalInfo(_fullName, _email, _phone, _address),
                new WorkHistory(_workEntries.Select(e =>
                    new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList()),
                _references.Select(r =>
                    new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                _coverLetter
            );

            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _submitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}
