+
+    // Submission state
+    private bool _isSubmitting;
+    private bool _submitted;
+    private int _applicationId;
+    private string? _submitError;
+
+    private void GoToStep(int step)
+    {
+        if (step < _currentStep || _completedSteps.Contains(step) || step == _currentStep)
+        {
+            _validationError = null;
+            _currentStep = step;
+        }
+    }
+
+    private void GoBack()
+    {
+        if (_currentStep > 1)
+        {
+            _validationError = null;
+            _currentStep--;
+        }
+    }
+
+    private async Task HandlePersonalInfoNext()
+    {
+        _validationError = null;
+
+        if (string.IsNullOrWhiteSpace(_fullName))
+        { _validationError = "Full name is required."; return; }
+        if (string.IsNullOrWhiteSpace(_email))
+        { _validationError = "Email is required."; return; }
+        if (string.IsNullOrWhiteSpace(_phone))
+        { _validationError = "Phone number is required."; return; }
+        if (string.IsNullOrWhiteSpace(_address))
+        { _validationError = "Address is required."; return; }
+
+        var emailValid = await ApplicationService.ValidateEmailAsync(_email);
+        if (!emailValid)
+        { _validationError = "Please enter a valid email address."; return; }
+
+        _completedSteps.Add(1);
+        _currentStep = 2;
+    }
+
+    private void HandleWorkHistoryNext()
+    {
+        _validationError = null;
+
+        foreach (var entry in _workEntries)
+        {
+            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
+            { _validationError = "Company name and job title are required for all entries."; return; }
+            if (entry.StartDate == default)
+            { _validationError = "Start date is required for all entries."; return; }
+        }
+
+        _completedSteps.Add(2);
+        _currentStep = 3;
+    }
+
+    private void HandleReferencesNext()
+    {
+        _validationError = null;
+
+        foreach (var r in _references)
+        {
+            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email))
+            { _validationError = "Name and email are required for all references."; return; }
+        }
+
+        _completedSteps.Add(3);
+        _currentStep = 4;
+    }
+
+    private void HandleCoverLetterNext()
+    {
+        _validationError = null;
+
+        if (string.IsNullOrWhiteSpace(_coverLetter))
+        { _validationError = "Cover letter is required."; return; }
+
+        _completedSteps.Add(4);
+        _currentStep = 5;
+    }
+
+    private async Task HandleSubmit()
+    {
+        _isSubmitting = true;
+        _submitError = null;
+
+        try
+        {
+            var application = new JobApplication(
+                new PersonalInfo(_fullName, _email, _phone, _address),
+                new WorkHistory(_workEntries.Select(e =>
+                    new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList()),
+                _references.Select(r =>
+                    new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
+                _coverLetter
+            );
+
+            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
+            _submitted = true;
+        }
+        catch (Exception ex)
+        {
+            _submitError = $"Submission failed: {ex.Message}";
+        }
+        finally
+        {
+            _isSubmitting = false;
+        }
+    }
+
+    public class WorkEntryModel
+    {
+        public string Company { get; set; } = "";
+        public string Title { get; set; } = "";
+        public DateTime StartDate { get; set; }
+        public DateTime? EndDate { get; set; }
+        public bool IsCurrent { get; set; }
+        public string Description { get; set; } = "";
+    }
+
+    public class ReferenceModel
+    {
+        public string Name { get; set; } = "";
+        public string Relationship { get; set; } = "";
+        public string Email { get; set; } = "";
+        public string Phone { get; set; } = "";
+    }
+}
